"""mini_jsonpath:在嵌套结构里按路径取值。

支持 ``$.a.b``、``$.a[*]``(取列表全部元素)、``$.a[n]``(取列表第 n 个元素),
各段可自由组合,如 ``$.servers[*].name``。
"""

from __future__ import annotations

from typing import Any


def select(data: Any, path: str) -> Any:
    """按 path 从 data 中取值。

    path 形如 ``$.a.b``、``$.a[*]``、``$.a[*].b`` 或 ``$.a[0]``。
    缺失键或索引越界抛 KeyError;path 不以 ``$.`` 开头抛 ValueError。
    """
    if not path.startswith('$.'):
        raise ValueError(path)
    parts = [p for p in path[2:].split('.') if p]
    node: Any = data
    for i, part in enumerate(parts):
        key, index = _parse_part(part)
        if not isinstance(node, dict) or key not in node:
            raise KeyError(key)
        node = node[key]
        if index is None:
            continue
        if not isinstance(node, list):
            raise KeyError(key)
        if index == '*':
            rest = '.'.join(parts[i + 1:])
            if not rest:
                return node
            return [select(item, '$.' + rest) for item in node]
        try:
            node = node[index]
        except IndexError:
            raise KeyError(index) from None
    return node


def _parse_part(part: str) -> tuple[str, Any]:
    """把路径段拆成 (键, 索引):无索引为 None,``[*]`` 为 ``'*'``,``[n]`` 为整数。"""
    if not part.endswith(']'):
        return part, None
    bracket = part.find('[')
    if bracket == -1:
        raise ValueError(part)
    key = part[:bracket]
    inner = part[bracket + 1:-1]
    if inner == '*':
        return key, '*'
    try:
        return key, int(inner)
    except ValueError:
        raise ValueError(part) from None
